import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Tabs einrichten","description":"Die untere Navigationsleiste der App über das Grid „tabs\\" zusammenstellen.","frontmatter":{"title":"Tabs einrichten","description":"Die untere Navigationsleiste der App über das Grid „tabs\\" zusammenstellen."},"headers":[],"relativePath":"apptiveteams/tabs.md","filePath":"apptiveteams/tabs.md","lastUpdated":1786357627000}'),d={name:"apptiveteams/tabs.md"};function r(s,e,o,l,c,b){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="tabs-einrichten" tabindex="-1">Tabs einrichten <a class="header-anchor" href="#tabs-einrichten" aria-label="Permalink to &quot;Tabs einrichten&quot;">​</a></h1><p>Jede Zeile im Grid mit dem Key <code>tabs</code> wird zu einem <strong>Tab</strong> in der unteren Navigationsleiste der App.</p><h2 id="die-felder" tabindex="-1">Die Felder <a class="header-anchor" href="#die-felder" aria-label="Permalink to &quot;Die Felder&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feld-Key</th><th>Feldtyp</th><th>Pflicht</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>title</code></td><td>Text</td><td>ja</td><td>Beschriftung des Tabs</td></tr><tr><td><code>icon</code></td><td>Anhang (SVG)</td><td>ja</td><td>Icon des Tabs</td></tr><tr><td><code>type</code></td><td>Text / Einzelauswahl</td><td>ja</td><td><code>TilesGrid</code>, <code>CardList</code> oder <code>WebView</code></td></tr><tr><td><code>gridUri</code></td><td>Interne Verknüpfung</td><td>bei <code>TilesGrid</code> und <code>CardList</code></td><td>Verweis auf das Grid mit den Inhalten</td></tr><tr><td><code>uri</code></td><td>Weblink</td><td>bei <code>WebView</code></td><td>Adresse, die im Tab angezeigt wird</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Einzelauswahl statt Freitext für <code>type</code></p><p>Legen Sie <code>type</code> als <strong>Einzelauswahl</strong> mit genau den drei Werten an. Das verhindert Tippfehler — ein Tab mit dem Wert <code>Tilesgrid</code> statt <code>TilesGrid</code> wird stillschweigend übersprungen.</p></div><h2 id="die-drei-tab-typen" tabindex="-1">Die drei Tab-Typen <a class="header-anchor" href="#die-drei-tab-typen" aria-label="Permalink to &quot;Die drei Tab-Typen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Typ</th><th>Zeigt</th><th>Braucht</th></tr></thead><tbody><tr><td><strong><code>TilesGrid</code></strong></td><td>ein Raster aus Kacheln</td><td><code>gridUri</code></td></tr><tr><td><strong><code>CardList</code></strong></td><td>eine Liste aus Karten</td><td><code>gridUri</code></td></tr><tr><td><strong><code>WebView</code></strong></td><td>eine eingebettete Webseite</td><td><code>uri</code></td></tr></tbody></table><p><code>TilesGrid</code> und <code>CardList</code> beziehen ihre Inhalte aus einem verknüpften Grid — je eine Zeile pro Kachel bzw. Karte.</p><p>→ <a href="/apptiveteams/kacheln-und-karten">Kacheln und Karten</a></p><h3 id="webview-tab" tabindex="-1">WebView-Tab <a class="header-anchor" href="#webview-tab" aria-label="Permalink to &quot;WebView-Tab&quot;">​</a></h3><p>Ein Tab vom Typ <code>WebView</code> bettet eine Webseite direkt in die App ein. Statt einer Grid-Verknüpfung tragen Sie im Feld <code>uri</code> die gewünschte Adresse ein — etwa Ihr Intranet, einen Schichtplan oder ein externes Portal.</p><div class="warning custom-block"><p class="custom-block-title">Nicht jede Seite lässt sich einbetten</p><p>Manche Websites verbieten die Anzeige in eingebetteten Ansichten. Der Tab bleibt dann leer. Prüfen Sie jede Adresse in der App, bevor Sie den Tab an die Belegschaft ausrollen.</p></div><h2 id="icons" tabindex="-1">Icons <a class="header-anchor" href="#icons" aria-label="Permalink to &quot;Icons&quot;">​</a></h2><p>Tab-Icons müssen <strong>SVG-Dateien</strong> sein. Die App färbt sie in Ihrer Primärfarbe ein — verwenden Sie deshalb <strong>einfarbige</strong> SVGs ohne eigene Farbflächen.</p><h2 id="die-navigationsleiste-erscheint-erst-ab-zwei-tabs" tabindex="-1">Die Navigationsleiste erscheint erst ab zwei Tabs <a class="header-anchor" href="#die-navigationsleiste-erscheint-erst-ab-zwei-tabs" aria-label="Permalink to &quot;Die Navigationsleiste erscheint erst ab zwei Tabs&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Ein einzelner Tab bekommt keine Leiste</p><p>Die untere Navigationsleiste wird erst ab <strong>zwei gültigen Tabs</strong> angezeigt. Bei genau einem Tab füllt dessen Inhalt den Bildschirm — das ist beabsichtigt und kein Fehler.</p></div><h2 id="zeilen-mit-lucken-werden-ubersprungen" tabindex="-1">Zeilen mit Lücken werden übersprungen <a class="header-anchor" href="#zeilen-mit-lucken-werden-ubersprungen" aria-label="Permalink to &quot;Zeilen mit Lücken werden übersprungen&quot;">​</a></h2><p>Fehlt einer Zeile ein Pflichtfeld, überspringt die App sie — ohne Meldung.</p><div class="tip custom-block"><p class="custom-block-title">Tab vorübergehend ausblenden</p><p>Das lässt sich nutzen: Leeren Sie den Titel einer Zeile, verschwindet der Tab aus der App, ohne dass Sie die Zeile und ihre Konfiguration löschen müssen. Zum Wiedereinblenden tragen Sie den Titel erneut ein.</p><p>Sauberer ist der Weg über eine gefilterte Ansicht als <code>tabs</code>-Grid — dort steuern Sie die Sichtbarkeit über ein eigenes Häkchenfeld, ohne Daten zu leeren.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/apptiveteams/kacheln-und-karten">Kacheln und Karten</a></li><li><a href="/apptiveteams/team-space">Team Space einrichten</a></li><li><a href="/apptiveteams/fehlerbehebung">Tipps und Fehlerbehebung</a></li></ul>',21)])])}const u=t(d,[["render",r]]);export{p as __pageData,u as default};
